edits.new:
// Create legend with fixed order to ensure all required sectors appear if present
const legendDiv = d3.select('#legend');
const requiredSectors = ['energy', 'financial', 'industry', 'information technology', 'etf'];
const allSectors = Array.from(new Set([...requiredSectors, ...sectors])).sort();

allSectors.forEach(sector => {
    // Only show if data exists or it's a required placeholder
    const hasData = sectors.includes(sector);
    if (!hasData && !requiredSectors.includes(sector)) return;

    const item = legendDiv.append('div').attr('class', 'legend-item');
    item.append('div')
        .attr('class', 'legend-color')
        .style('background-color', sectorColorMap[sector] || '#ccc');
    item.append('span').text(sector.charAt(0).toUpperCase() + sector.slice(1));
});
